#pragma once
#include <vector>
#include <cmath>
#include <ArduinoEigenDense.h>
#include "model_params.h" // generated by python/export_model_header.py

using namespace Eigen;

struct lda_model {
    std::vector<int> class_labels;
    std::vector<float> priors;
    int num_classes;
    MatrixXd inv_cov;
    MatrixXd centroids;
};

int predict(const VectorXd& x, const lda_model& model);

// Fills model from the baked-in parameters in model_params.h plus the live-calibrated
// centroids (one column per class, in MODEL_CLASS_IDS order)
void load_lda_model(lda_model& model, const MatrixXd& centroids);
